------------ lifeCycle ------------

function HomelandCheckInPopupCell:__init()
    self:CleanProperties()
end

function HomelandCheckInPopupCell:__delete()
    self:CleanProperties()
end

function HomelandCheckInPopupCell:Awake()
    ---@type HomelandCheckInComponent
    self.comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HomelandCheckInComponent)

    -- 属性组
    local lb = GetLuaBehaviour(self.LayoutGroup.gameObject, AttrNodeLuaPath)
    if isNotNull(lb) then
        ---@type HomelandCheckInEntryAttributeNode
        self.lt_attrNode = lb.Env
    end

    -- 点击底板选中小组
    if isNotNull(self.Imgbg) and isNotNull(self.SelectGroup) then
        SetButtonAction(self.Imgbg.gameObject, function()
            if self.type == 2 then
                Events.Broadcast(Constants.EventNames.HomelandCheckInPopupSelectGroup, self.data.groupId)
            end
        end)
    end

    -- 点击添加按钮
    if isNotNull(self.BtnAppend) then
        SetButtonAction(self.BtnAppend.gameObject, function()
            if self.type == 2 then
                self.comp:RequestBuild(self.data.groupId, function()
                    UIModule.BackDialog()
                    UIModule.OpenDialog({ id = Constants.UITypeIds.HomelandCheckInDialog, parameters = {groupId = self.data.groupId}})
                end)                
            end
        end)
    end
end

function HomelandCheckInPopupCell:Start()
    -- 点击底板时，改变组内的选中状态
    self.eventSelectGroup = Events.AddListener(Constants.EventNames.HomelandCheckInPopupSelectGroup, Bind(self, self.OnCellSelected))
end

function HomelandCheckInPopupCell:OnDestroy()
    Events.RemoveListener(Constants.EventNames.HomelandCheckInPopupSelectGroup, self.eventSelectGroup)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
------------ lifeCycle ------------


function HomelandCheckInPopupCell:CleanProperties()
    self.comp = nil
    self.data = nil
    self.type = nil
    self.eventSelectGroup = nil
end

function HomelandCheckInPopupCell:Refresh(data, type)
    self.data = data
    self.type = type
    local groupId = data.groupId
    -- 刷新头像
    local lb = GetLuaBehaviour(self.HeadTeam.gameObject, CardHeadTeamLuaPath)
    lb.Env:Refresh(groupId)

    -- 刷新属性
    if isNotNull(self.lt_attrNode) then
        local totalAttr = self.comp:GetGroupTotalUpgradeAttr(groupId)
        local attrAdditionalMax1 = self.comp:GetAttrAdditionalMax(groupId, 1)
        local attrAdditionalMax2 = self.comp:GetAttrAdditionalMax(groupId, 2)

        local data = {}
        for color, attrs in pairs(totalAttr) do
            for attrId, num in pairs(attrs) do
                local num1 = math.floor(num * attrAdditionalMax1 * attrAdditionalMax2)
                table.insert(data, {attrAddId = attrId, color = color, num = num1})
            end
        end

        table.sort(data, function(a,b)
            return a.attrAddId < b.attrAddId
        end)

        self.lt_attrNode:Refresh(data)
    end

    if type == 2 then
        -- 不可选择的遮罩
        if isNotNull(self.ImgBlack) then
            local hasNum = self.comp:GetHasCardNum(groupId)
            local cantSelect = hasNum <= 0
            KTool.SetActive(self.ImgBlack, cantSelect)
            CfUtils.FillText(self.TxtState, cantSelect and localize("未拥有战斗员") or localize("点击选择"))
        end
    
        -- 选中以后，滚动列表的话，会把这个选中状态带到其他的cell上，所以每次刷新的时候，都关闭一下这个select状态
        if isNotNull(self.SelectGroup) then
            KTool.SetActive(self.SelectGroup, false)
        end        
    end
end

function HomelandCheckInPopupCell:OnCellSelected(groupId)
    KTool.SetActive(self.SelectGroup, self.data.groupId == groupId)
end

return HomelandCheckInPopupCell